/// Optional parameters for the `/admin/rebalance` endpoint.
///
/// `Default::default()` is the empty set: only options set explicitly are
/// sent, and anything left empty falls back to the server's own default.
#[derive(Debug, Clone, Default)]
pub struct AdminRebalanceRequestOptions {
    /// If true, sharded data will be rebalanced approximately equally across
    /// the cluster. Note that for clusters with large amounts of sharded data,
    /// this data transfer could be time consuming and result in delayed query
    /// responses.
    /// Server default: `true`.
    pub rebalance_sharded_data: String,
    /// If true, unsharded data (a.k.a. randomly-sharded) will be rebalanced
    /// approximately equally across the cluster. Note that for clusters with
    /// large amounts of unsharded data, this data transfer could be time
    /// consuming and result in delayed query responses.
    /// Server default: `true`.
    pub rebalance_unsharded_data: String,
    /// Comma-separated list of unsharded table names to rebalance. Not
    /// applicable to sharded tables because they are always rebalanced. Cannot
    /// be used simultaneously with table_excludes. This parameter is ignored if
    /// rebalance_unsharded_data is false.
    pub table_includes: String,
    /// Comma-separated list of unsharded table names to not rebalance. Not
    /// applicable to sharded tables because they are always rebalanced. Cannot
    /// be used simultaneously with table_includes. This parameter is ignored if
    /// rebalance_unsharded_data is false.
    pub table_excludes: String,
    /// Influences how much data is moved at a time during rebalance. A higher
    /// aggressiveness will complete the rebalance faster. A lower
    /// aggressiveness will take longer but allow for better interleaving
    /// between the rebalance and other queries. Valid values are constants from
    /// 1 (lowest) to 10 (highest).
    /// Server default: `10`.
    pub aggressiveness: String,
    /// Perform compaction of deleted records once the rebalance completes to
    /// reclaim memory and disk space. Default is true, unless
    /// repair_incorrectly_sharded_data is set to true.
    /// Server default: `true`.
    pub compact_after_rebalance: String,
    /// If set to true, ignore rebalance options and attempt to perform
    /// compaction of deleted records to reclaim memory and disk space without
    /// rebalancing first.
    /// Server default: `false`.
    pub compact_only: String,
    /// Scans for any data sharded incorrectly and re-routes the data to the
    /// correct location. Only necessary if `/admin/verifydb` reports an error
    /// in sharding alignment. This can be done as part of a typical rebalance
    /// after expanding the cluster or in a standalone fashion when it is
    /// believed that data is sharded incorrectly somewhere in the cluster.
    /// Compaction will not be performed by default when this is enabled. If
    /// this option is set to true, the time necessary to rebalance and the
    /// memory used by the rebalance may increase.
    /// Server default: `false`.
    pub repair_incorrectly_sharded_data: String,
}

impl AdminRebalanceRequestOptions {
    /// Converts the set (non-empty) options into the wire-format string map.
    pub fn to_map(&self) -> std::collections::HashMap<String, String> {
        let mut m = std::collections::HashMap::new();
        if !self.rebalance_sharded_data.is_empty() {
            m.insert(
                "rebalance_sharded_data".to_string(),
                self.rebalance_sharded_data.clone(),
            );
        }
        if !self.rebalance_unsharded_data.is_empty() {
            m.insert(
                "rebalance_unsharded_data".to_string(),
                self.rebalance_unsharded_data.clone(),
            );
        }
        if !self.table_includes.is_empty() {
            m.insert("table_includes".to_string(), self.table_includes.clone());
        }
        if !self.table_excludes.is_empty() {
            m.insert("table_excludes".to_string(), self.table_excludes.clone());
        }
        if !self.aggressiveness.is_empty() {
            m.insert("aggressiveness".to_string(), self.aggressiveness.clone());
        }
        if !self.compact_after_rebalance.is_empty() {
            m.insert(
                "compact_after_rebalance".to_string(),
                self.compact_after_rebalance.clone(),
            );
        }
        if !self.compact_only.is_empty() {
            m.insert("compact_only".to_string(), self.compact_only.clone());
        }
        if !self.repair_incorrectly_sharded_data.is_empty() {
            m.insert(
                "repair_incorrectly_sharded_data".to_string(),
                self.repair_incorrectly_sharded_data.clone(),
            );
        }
        m
    }
}

