pub struct CreateTableExternalResponse {
    /// Value of `table_name`.
    pub table_name: String,
    /// ID of the currently registered table structure type for this external
    /// table.
    pub type_id: String,
    /// A JSON string describing the columns of the created external table.
    pub type_definition: String,
    /// The user-defined description associated with the table's structure.
    pub type_label: String,
    /// A mapping of each external table column name to an array of column
    /// properties associated with that column.
    pub type_properties: std::collections::HashMap<String, Vec<String>>,
    /// Number of records inserted into the external table.
    pub count_inserted: i64,
    /// Number of records skipped, when not running in abort error handling
    /// mode.
    pub count_skipped: i64,
    /// \[Not yet implemented\] Number of records updated within the external
    /// table.
    pub count_updated: i64,
    /// Additional information.
    pub info: std::collections::HashMap<String, String>,
    /// The list of source files used to create the external table.
    pub files: Vec<String>,
}

/// The request payload for the `/create/tablemonitor` endpoint.
///
/// Create a table monitor that will watch for and queue any records added
#[derive(Debug, Clone, Default, serde::Serialize, serde::Deserialize)]
pub struct CreateTableMonitorRequest {
    /// Name of the table to monitor, in \[schema_name.\]table_name format,
    /// using standard name resolution rules.
    pub table_name: String,
    /// Optional parameters.
    pub options: std::collections::HashMap<String, String>,
}

impl crate::KineticaRecord for CreateTableMonitorRequest {
    fn avro_schema(&self) -> &'static str {
        CREATE_TABLE_MONITOR_REQUEST_AVRO
    }

    fn type_properties() -> std::collections::HashMap<String, Vec<String>> {
        std::collections::HashMap::from([
            ("table_name".to_string(), vec!["string".to_string()]),
            ("options".to_string(), vec!["string".to_string()]),
        ])
    }
}

/// Optional parameters for the `/create/tablemonitor` endpoint.
///
/// `Default::default()` is the empty set: only options set explicitly are
/// sent, and anything left empty falls back to the server's own default.
#[derive(Debug, Clone, Default)]
pub struct CreateTableMonitorRequestOptions {
    /// Type of modification event on the target table to be monitored by this
    /// table monitor.
    /// Server default: `insert`.
    pub event: String,
    /// ID to use for this monitor instead of a randomly generated one.
    pub monitor_id: String,
    /// Name of an existing data sink to send change data notifications to.
    pub datasink_name: String,
    /// Maximum number of consecutive failed notification attempts before
    /// suspending the stream. A value of -1 (default) disables auto-suspend.
    /// This value is by rank and not overall.
    pub max_consecutive_failures: String,
    /// Name of a table to which failed stream notifications are written when
    /// the stream is suspended. The database will attempt to send notifications
    /// persisted in this table when the stream is resumed. The table has the
    /// following columns: rank (long), job_id (long), uuid (uuid), timestamp
    /// (timestamp), error_msg (string), payload (bytes). Leave this option
    /// empty to disable persisting failed notification events.
    pub failed_notifications_table_name: String,
    /// Destination for the output data in format
    /// 'destination_type://path\[:port\]'. Supported destination types are
    /// 'http', 'https' and 'kafka'.
    pub destination: String,
    /// Name of the Kafka topic to publish to if destination in `options` is
    /// specified and is a Kafka broker.
    pub kafka_topic_name: String,
    /// Column on subscribed table that will increase for new records (e.g.,
    /// TIMESTAMP).
    pub increasing_column: String,
    /// Filter expression to limit records for notification.
    pub expression: String,
    /// A comma-separated list of tables (optionally with aliases) to include in
    /// the join. The monitored table `table_name` must be included,
    /// representing only the newly inserted rows (deltas) since the last
    /// notification. Other tables can be any existing tables or views. Aliases
    /// can be used with the 'table_name as alias' syntax.
    pub join_table_names: String,
    /// A comma-separated list of columns or expressions to include from the
    /// joined tables. Column references can use table names or aliases defined
    /// in 'join_table_names'. Each column can optionally be aliased using 'as'.
    /// The selected columns will also appear in the notification output.
    pub join_column_names: String,
    /// Filter or join expressions to apply when combining the tables.
    /// Expressions are standard SQL-style conditions and can reference any
    /// table or alias listed in 'join_table_names'. This corresponds to the
    /// WHERE clause of the underlying join, and can include conditions to
    /// filter the delta rows.
    pub join_expressions: String,
    /// Method controlling when the table monitor reports changes to the
    /// `table_name`.
    /// Server default: `on_change`.
    pub refresh_method: String,
    /// When refresh_method is periodic, specifies the period in seconds at
    /// which changes are reported.
    pub refresh_period: String,
    /// When refresh_method is periodic, specifies the first time at which
    /// changes are reported. Value is a datetime string with format 'YYYY-MM-DD
    /// HH:MM:SS'.
    pub refresh_start_time: String,
}

