/// Optional parameters for the `/execute/proc` endpoint.
///
/// `Default::default()` is the empty set: only options set explicitly are
/// sent, and anything left empty falls back to the server's own default.
#[derive(Debug, Clone, Default)]
pub struct ExecuteProcRequestOptions {
    /// No longer supported; option will be ignored.
    pub cache_input: String,
    /// No longer supported; option will be ignored.
    pub use_cached_input: String,
    /// A string that, if not empty, can be used in subsequent calls to
    /// `/show/proc/status` or `/kill/proc` to identify the proc instance.
    pub run_tag: String,
    /// The maximum number of lines of output from stdout and stderr to return
    /// via `/show/proc/status`. If the number of lines output exceeds the
    /// maximum, earlier lines are discarded.
    /// Server default: `100`.
    pub max_output_lines: String,
    /// If true, an instance of the proc will run when the database is started
    /// instead of running immediately. The `run_id` can be retrieved using
    /// `/show/proc` and used in `/show/proc/status`.
    /// Server default: `false`.
    pub execute_at_startup: String,
    /// Sets the alternate user name to execute this proc instance as when
    /// execute_at_startup is true.
    pub execute_at_startup_as: String,
}

impl ExecuteProcRequestOptions {
    /// Converts the set (non-empty) options into the wire-format string map.
    pub fn to_map(&self) -> std::collections::HashMap<String, String> {
        let mut m = std::collections::HashMap::new();
        if !self.cache_input.is_empty() {
            m.insert("cache_input".to_string(), self.cache_input.clone());
        }
        if !self.use_cached_input.is_empty() {
            m.insert(
                "use_cached_input".to_string(),
                self.use_cached_input.clone(),
            );
        }
        if !self.run_tag.is_empty() {
            m.insert("run_tag".to_string(), self.run_tag.clone());
        }
        if !self.max_output_lines.is_empty() {
            m.insert(
                "max_output_lines".to_string(),
                self.max_output_lines.clone(),
            );
        }
        if !self.execute_at_startup.is_empty() {
            m.insert(
                "execute_at_startup".to_string(),
                self.execute_at_startup.clone(),
            );
        }
        if !self.execute_at_startup_as.is_empty() {
            m.insert(
                "execute_at_startup_as".to_string(),
                self.execute_at_startup_as.clone(),
            );
        }
        m
    }
}

