/// Optional parameters for the `/update/records` endpoint.
///
/// `Default::default()` is the empty set: only options set explicitly are
/// sent, and anything left empty falls back to the server's own default.
#[derive(Debug, Clone, Default)]
pub struct UpdateRecordsRequestOptions {
    /// An optional global expression to reduce the search space of the
    /// predicates listed in `expressions`.
    pub global_expression: String,
    /// When set to true, all predicates are available for primary key updates.
    /// Keep in mind that it is possible to destroy data in this case, since a
    /// single predicate may match multiple objects (potentially all of records
    /// of a table), and then updating all of those records to have the same
    /// primary key will, due to the primary key uniqueness constraints,
    /// effectively delete all but one of those updated records.
    /// Server default: `false`.
    pub bypass_safety_checks: String,
    /// Specifies how record errors are handled during the update's reinsert
    /// (including any alternate insert records supplied via
    /// `records_to_insert`). When set, this option is authoritative for the
    /// reinsert. Primary-key collision behavior is governed by
    /// update_on_existing_pk and ignore_existing_pk.
    /// Server default: `abort`.
    pub error_handling: String,
    /// Specifies the record collision policy for updating a table with a
    /// primary key. There are two ways that a record collision can occur.
    ///
    /// The first is an "update collision", which happens when the update
    /// changes the value of the updated record's primary key, and that new
    /// primary key already exists as the primary key of another record in the
    /// table.
    ///
    /// The second is an "insert collision", which occurs when a given filter in
    /// `expressions` finds no records to update, and the alternate insert
    /// record given in `records_to_insert` (or `records_to_insert_str`)
    /// contains a primary key matching that of an existing record in the table.
    ///
    /// If update_on_existing_pk is set to true, "update collisions" will result
    /// in the existing record collided into being removed and the record
    /// updated with values specified in `new_values_maps` taking its place;
    /// "insert collisions" will result in the collided-into record being
    /// updated with the values in `records_to_insert` / `records_to_insert_str`
    /// (if given).
    ///
    /// If set to false, the existing collided-into record will remain
    /// unchanged, while the update will be rejected and the error handled as
    /// determined by ignore_existing_pk. If the specified table does not have a
    /// primary key, then this option has no effect.
    /// Server default: `false`.
    pub update_on_existing_pk: String,
    /// The record with higher value for the column resolves the primary-key
    /// insert conflict.
    pub pk_conflict_predicate_higher: String,
    /// The record with lower value for the column resolves the primary-key
    /// insert conflict.
    pub pk_conflict_predicate_lower: String,
    /// Specifies the record collision error-suppression policy for updating a
    /// table with a primary key, only used when primary key record collisions
    /// are rejected (update_on_existing_pk is false). If set to true, any
    /// record update that is rejected for resulting in a primary key collision
    /// with an existing table record will be ignored with no error generated.
    /// If false, the rejection of any update for resulting in a primary key
    /// collision will cause an error to be reported. If the specified table
    /// does not have a primary key or if update_on_existing_pk is true, then
    /// this option has no effect.
    /// Server default: `false`.
    pub ignore_existing_pk: String,
    /// Force qualifying records to be deleted and reinserted so their partition
    /// membership will be reevaluated.
    /// Server default: `false`.
    pub update_partition: String,
    /// If set to true, qualifying records are modified in place. If set to
    /// false, they are updated by deleting the existing record and inserting a
    /// replacement (delete and insert), which prevents the change from being
    /// reflected in dependent materialized views until they are refreshed.
    /// Server default: `true`.
    pub enable_inplace_updates: String,
    /// If set to true, any strings which are too long for their charN string
    /// fields will be truncated to fit.
    /// Server default: `false`.
    pub truncate_strings: String,
    /// When set to true, all new values in `new_values_maps` are considered as
    /// expression values. When set to false, all new values in
    /// `new_values_maps` are considered as constants. NOTE: When true, string
    /// constants will need to be quoted to avoid being evaluated as
    /// expressions.
    /// Server default: `false`.
    pub use_expressions_in_new_values_maps: String,
    /// ID of a single record to be updated (returned in the call to
    /// `/insert/records` or `/get/records/fromcollection`).
    pub record_id: String,
}

impl UpdateRecordsRequestOptions {
    /// Converts the set (non-empty) options into the wire-format string map.
    pub fn to_map(&self) -> std::collections::HashMap<String, String> {
        let mut m = std::collections::HashMap::new();
        if !self.global_expression.is_empty() {
            m.insert(
                "global_expression".to_string(),
                self.global_expression.clone(),
            );
        }
        if !self.bypass_safety_checks.is_empty() {
            m.insert(
                "bypass_safety_checks".to_string(),
                self.bypass_safety_checks.clone(),
            );
        }
        if !self.error_handling.is_empty() {
            m.insert("error_handling".to_string(), self.error_handling.clone());
        }
        if !self.update_on_existing_pk.is_empty() {
            m.insert(
                "update_on_existing_pk".to_string(),
                self.update_on_existing_pk.clone(),
            );
        }
        if !self.pk_conflict_predicate_higher.is_empty() {
            m.insert(
                "pk_conflict_predicate_higher".to_string(),
                self.pk_conflict_predicate_higher.clone(),
            );
        }
        if !self.pk_conflict_predicate_lower.is_empty() {
            m.insert(
                "pk_conflict_predicate_lower".to_string(),
                self.pk_conflict_predicate_lower.clone(),
            );
        }
        if !self.ignore_existing_pk.is_empty() {
            m.insert(
                "ignore_existing_pk".to_string(),
                self.ignore_existing_pk.clone(),
            );
        }
        if !self.update_partition.is_empty() {
            m.insert(
                "update_partition".to_string(),
                self.update_partition.clone(),
            );
        }
        if !self.enable_inplace_updates.is_empty() {
            m.insert(
                "enable_inplace_updates".to_string(),
                self.enable_inplace_updates.clone(),
            );
        }
        if !self.truncate_strings.is_empty() {
            m.insert(
                "truncate_strings".to_string(),
                self.truncate_strings.clone(),
            );
        }
        if !self.use_expressions_in_new_values_maps.is_empty() {
            m.insert(
                "use_expressions_in_new_values_maps".to_string(),
                self.use_expressions_in_new_values_maps.clone(),
            );
        }
        if !self.record_id.is_empty() {
            m.insert("record_id".to_string(), self.record_id.clone());
        }
        m
    }
}

