    /// Constants for the fields of the `/export/records/tofiles` request.
    pub mod export_records_to_files_request {
        /// Constants for `options`.
        pub mod options {
            /// Number of records to be exported as a batch.
            pub const BATCH_SIZE: &str = "batch_size";
            /// For each source column specified, applies the
            /// column-property-bound format. Currently supported column
            /// properties include date, time, and datetime. The parameter value
            /// must be formatted as a JSON string of maps of column names to
            /// maps of column properties to their corresponding column formats,
            /// e.g., '{ "order_date" : { "date" : "%Y.%m.%d" }, "order_time" :
            /// { "time" : "%H:%M:%S" } }'.
            ///
            /// See default_column_formats for valid format syntax.
            pub const COLUMN_FORMATS: &str = "column_formats";
            /// Specifies a comma-delimited list of columns from the source
            /// table to export, written to the output file in the order they
            /// are given.
            ///
            /// Column names can be provided, in which case the target file will
            /// use those names as the column headers as well.
            ///
            /// Alternatively, column numbers can be specified--discretely or as
            /// a range. For example, a value of '5,7,1..3' will write values
            /// from the fifth column in the source table into the first column
            /// in the target file, from the seventh column in the source table
            /// into the second column in the target file, and from the first
            /// through third columns in the source table into the third through
            /// fifth columns in the target file.
            ///
            /// Mutually exclusive with columns_to_skip.
            pub const COLUMNS_TO_EXPORT: &str = "columns_to_export";
            /// Comma-separated list of column names or column numbers to not
            /// export. All columns in the source table not specified will be
            /// written to the target file in the order they appear in the table
            /// definition. Mutually exclusive with columns_to_export.
            pub const COLUMNS_TO_SKIP: &str = "columns_to_skip";
            /// Datasink name, created using `/create/datasink`.
            pub const DATASINK_NAME: &str = "datasink_name";
            /// Specifies the default format to use to write data. Currently
            /// supported column properties include date, time, and datetime.
            /// This default column-property-bound format can be overridden by
            /// specifying a column property and format for a given source
            /// column in column_formats. For each specified annotation, the
            /// format will apply to all columns with that annotation unless
            /// custom column_formats for that annotation are specified.
            ///
            /// The parameter value must be formatted as a JSON string that is a
            /// map of column properties to their respective column formats,
            /// e.g., '{ "date" : "%Y.%m.%d", "time" : "%H:%M:%S" }'. Column
            /// formats are specified as a string of control characters and
            /// plain text. The supported control characters are 'Y', 'm', 'd',
            /// 'H', 'M', 'S', and 's', which follow the Linux 'strptime()'
            /// specification, as well as 's', which specifies seconds and
            /// fractional seconds (though the fractional component will be
            /// truncated past milliseconds).
            ///
            /// Formats for the 'date' annotation must include the 'Y', 'm', and
            /// 'd' control characters. Formats for the 'time' annotation must
            /// include the 'H', 'M', and either 'S' or 's' (but not both)
            /// control characters. Formats for the 'datetime' annotation meet
            /// both the 'date' and 'time' control character requirements. For
            /// example, '{"datetime" : "%m/%d/%Y %H:%M:%S" }' would be used to
            /// write text as "05/04/2000 12:12:11"
            pub const DEFAULT_COLUMN_FORMATS: &str = "default_column_formats";
            /// Save DDL to a separate file.
            pub const EXPORT_DDL: &str = "export_ddl";
            /// Extension to give the export file.
            pub const FILE_EXTENSION: &str = "file_extension";
            /// Specifies the file format to use when exporting data.
            pub const FILE_TYPE: &str = "file_type";
            /// Delimited text file format; e.g., CSV, TSV, PSV, etc.
            pub const DELIMITED_TEXT: &str = "delimited_text";
            pub const PARQUET: &str = "parquet";
            /// Whether to include a Kinetica proprietary header. Will not be
            /// written if text_has_header is false.
            pub const KINETICA_HEADER: &str = "kinetica_header";
            pub const TRUE: &str = "true";
            pub const FALSE: &str = "false";
            /// If a Kinetica proprietary header is included, then specify a
            /// property separator. Different from column delimiter.
            pub const KINETICA_HEADER_DELIMITER: &str = "kinetica_header_delimiter";
            /// File compression type. GZip can be applied to text and Parquet
            /// files. Snappy can only be applied to Parquet files, and is the
            /// default compression for them.
            pub const COMPRESSION_TYPE: &str = "compression_type";
            pub const UNCOMPRESSED: &str = "uncompressed";
            pub const SNAPPY: &str = "snappy";
            pub const GZIP: &str = "gzip";
            /// Save records to a single file. This option may be ignored if
            /// file size exceeds internal file size limits (this limit will
            /// differ on different targets).
            pub const SINGLE_FILE: &str = "single_file";
            pub const OVERWRITE: &str = "overwrite";
            /// Max file size (in MB) to allow saving to a single file. May be
            /// overridden by target limitations.
            pub const SINGLE_FILE_MAX_SIZE: &str = "single_file_max_size";
            /// Specifies the character to write out to delimit field values and
            /// field names in the header (if present).
            ///
            /// For delimited_text file_type only.
            pub const TEXT_DELIMITER: &str = "text_delimiter";
            /// Indicates whether to write out a header row.
            ///
            /// For delimited_text file_type only.
            pub const TEXT_HAS_HEADER: &str = "text_has_header";
            /// Specifies the character string that should be written out for
            /// the null value in the data.
            ///
            /// For delimited_text file_type only.
            pub const TEXT_NULL_STRING: &str = "text_null_string";
        }
    }

